import java.util.Scanner;
public class SecondLargestArray { public static void main(String[] x){Scanner s=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!s.hasNextInt()){System.out.println("Enter a size from 1 to 100.");return;}int n=s.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}int largest=0,second=0;boolean hasLargest=false,hasSecond=false;for(int i=0;i<n;i++){if(!s.hasNextInt()){System.out.println("Enter exactly "+n+" whole numbers.");return;}int v=s.nextInt();if(!hasLargest||v>largest){if(hasLargest){second=largest;hasSecond=true;}largest=v;hasLargest=true;}else if(v<largest&&(!hasSecond||v>second)){second=v;hasSecond=true;}}if(s.hasNext()){System.out.println("Enter only the array values.");return;}if(hasSecond)System.out.println("Second largest distinct value: "+second);else System.out.println("No distinct second largest value.");}}
